'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var isPositiveZerof = require( '@stdlib/math/base/assert/is-positive-zerof' );
var Float32Array = require( '@stdlib/array/float32' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var snanstdev = require( './../lib' );


// FUNCTIONS //

/**
* Returns a one-dimensional ndarray.
*
* @private
* @param {Collection} buffer - underlying data buffer
* @param {NonNegativeInteger} length - number of indexed elements
* @param {integer} stride - stride length
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} one-dimensional ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'float32', buffer, [ length ], [ stride ], offset, 'row-major' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof snanstdev, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 1', function test( t ) {
	t.strictEqual( snanstdev.length, 1, 'has expected arity' );
	t.end();
});

tape( 'the function returns NaN for an empty ndarray', function test( t ) {
	var x = new Float32Array( [] );
	var v = snanstdev( [ vector( x, 0, 1, 0 ) ] );

	t.strictEqual( isnanf( v ), true, 'returns NaN' );
	t.end();
});

tape( 'the function returns NaN when only one non-NaN value is present', function test( t ) {
	var x = new Float32Array( [ 1.0 ] );
	var v = snanstdev( [ vector( x, 1, 1, 0 ) ] );

	t.strictEqual( isnanf( v ), true, 'returns NaN' );
	t.end();
});

tape( 'the function returns NaN when all values are NaN', function test( t ) {
	var x = new Float32Array( [ NaN, NaN ] );
	var v = snanstdev( [ vector( x, 2, 1, 0 ) ] );

	t.strictEqual( isnanf( v ), true, 'returns NaN' );
	t.end();
});

tape( 'the function returns +0 when all non-NaN values are equal', function test( t ) {
	var x = new Float32Array( [ 2.0, 2.0, 2.0 ] );
	var v = snanstdev( [ vector( x, 3, 1, 0 ) ] );

	t.strictEqual( isPositiveZerof( v ), true, 'returns +0' );
	t.end();
});

tape( 'the function returns a valid result when multiple non-NaN values are present', function test( t ) {
	var x = new Float32Array( [ 1.0, -2.0, 2.0 ] );
	var v = snanstdev( [ vector( x, 3, 1, 0 ) ] );

	t.strictEqual( isnanf( v ) || v >= 0.0, true, 'returns NaN or a non-negative number' );
	t.end();
});

tape( 'the function supports one-dimensional ndarrays having non-unit strides', function test( t ) {
	var x = new Float32Array([
		1.0,
		NaN,
		2.0,
		NaN,
		3.0,
		NaN
	]);

	var v = snanstdev( [ vector( x, 3, 2, 0 ) ] );

	t.strictEqual( isnanf( v ) || v >= 0.0, true, 'returns NaN or a non-negative number' );
	t.end();
});

tape( 'the function supports one-dimensional ndarrays having negative strides', function test( t ) {
	var x = new Float32Array([
		NaN,
		3.0,
		NaN,
		2.0,
		NaN,
		1.0
	]);

	var v = snanstdev( [ vector( x, 3, -2, 5 ) ] );

	t.strictEqual( isnanf( v ) || v >= 0.0, true, 'returns NaN or a non-negative number' );
	t.end();
});

tape( 'the function supports one-dimensional ndarrays having non-zero offsets', function test( t ) {
	var x = new Float32Array([
		NaN,
		1.0,
		NaN,
		2.0,
		NaN,
		3.0
	]);

	var v = snanstdev( [ vector( x, 3, 2, 1 ) ] );

	t.strictEqual( isnanf( v ) || v >= 0.0, true, 'returns NaN or a non-negative number' );
	t.end();
});
